// Facebook webhook-оос ирсэн мессеж/postback-ийг задлах
// Текст мессеж + Get Started/Ice Breaker postback-ийг боловсруулна.
const body = $input.first().json.body;
if (!body || body.object !== 'page') return [];

// Get Started болон Ice Breaker payload-уудыг текст асуулт болгон хөрвүүлнэ
// → AI Agent ердийн хайлт/хариулт хийнэ.
const PAYLOAD_TO_TEXT = {
  GET_STARTED: '__GET_STARTED__',
  IB_PROJECTS: 'бэлэн төсөл',
  IB_BOOKS: 'ном',
  IB_PRICING: 'үнэ төлбөрийн мэдээлэл',
  IB_DOWNLOAD: 'татаж авах заавар',
};

const out = [];
for (const entry of (body.entry || [])) {
  for (const msg of (entry.messaging || [])) {
    const psid = String(msg.sender && msg.sender.id || '');
    if (!psid) continue;

    // 1) Postback (Get Started товч, Ice Breaker асуулт)
    if (msg.postback && msg.postback.payload) {
      const mapped = PAYLOAD_TO_TEXT[msg.postback.payload];
      const text = mapped || String(msg.postback.title || msg.postback.payload).trim();
      out.push({ json: { psid, text, isPostback: true } });
      continue;
    }

    // 2) Энгийн текст мессеж (echo, attachment алгасна)
    if (msg.message && !msg.message.is_echo && msg.message.text) {
      out.push({ json: { psid, text: String(msg.message.text).trim(), isPostback: false } });
    }
  }
}
return out;

const NL = String.fromCharCode(10);
const psid = $('Parse').first().json.psid;
const userText = $('Parse').first().json.text;
const profile = $('Get User Profile').first().json || {};
const firstName = (profile.first_name || '').trim();
const search = $('Search DigitalGer').first().json || {};
const products = Array.isArray(search.products) ? search.products : [];
const faqs = Array.isArray(search.faqs) ? search.faqs : [];
const searchTerms = Array.isArray(search.searchTerms) ? search.searchTerms : [];
const fmt = (n) => { const num = Math.round(Number(n)||0); return String(num).replace(/B(?=(d{3})+(?!d))/g, ',') + '₮'; };
const productsText = products.length
  ? products.slice(0, 5).map((p, i) => {
      const priceLine = (p.salePrice != null)
        ? ('Үнэ: ' + fmt(p.price) + ', хямдарсан үнэ: ' + fmt(p.salePrice))
        : ('Үнэ: ' + fmt(p.price));
      const kw = (p.matchedKeywords||[]).join(', ') || 'ойролцоо тохирол';
      return (i+1) + '. ' + p.title + NL + '   Төрөл: ' + p.productType + NL + '   ' + priceLine + NL + '   Тайлбар: ' + p.description + NL + '   (хайлтын үг: ' + kw + ')';
    }).join(NL + NL)
  : '(Бүтээгдэхүүн олдсонгүй)';
const faqsText = faqs.length
  ? faqs.slice(0, 3).map((f, i) => (i+1) + '. Асуулт: ' + f.question + NL + '   Хариулт: ' + f.answer).join(NL + NL)
  : '(FAQ олдсонгүй)';
const isGetStarted = (userText === '__GET_STARTED__');
const nameLine = firstName ? ('Хэрэглэгчийн нэр: ' + firstName) : 'Хэрэглэгчийн нэр: (тодорхойгүй)';
let agentInput;
if (isGetStarted) {
  agentInput = [
    nameLine,
    '',
    '=== ОНЦГОЙ НӨХЦӨЛ: Хэрэглэгч анх удаа чатад орж ирлээ ===',
    'Дулаан, найрсаг угтах мэндчилгээ бич. DigitalGer.mn дээр бэлэн төсөл, 1000+ ном, албан баримтын загвар байдгийг товч танилцуул. Юу хайж байгааг нь асуу. 2-4 өгүүлбэр.',
  ].join(NL);
} else {
  const termsLine = searchTerms.length ? ('=== ХАЙЛТЫН ГОЛ ҮГ: ' + searchTerms.join(', ') + ' ===') : '';
  agentInput = [
    nameLine,
    '',
    '=== ХЭРЭГЛЭГЧИЙН МЕССЕЖ ===',
    userText,
    '',
    termsLine,
    '=== ХАЙЛТЫН ҮР ДҮН: БҮТЭЭГДЭХҮҮН ===',
    productsText,
    '',
    '=== ХАЙЛТЫН ҮР ДҮН: FAQ ===',
    faqsText,
  ].filter(function(x){return x !== '';}).join(NL);
}
return [{ json: { psid, userText, firstName, agentInput, products, faqs, searchTerms, hasProducts: products.length > 0, nothingFound: (products.length === 0 && faqs.length === 0) } }];

const NL = String.fromCharCode(10);
const TUG = String.fromCharCode(0x20AE);
const psid = $('Prep Context').first().json.psid;
const products = $('Prep Context').first().json.products || [];
const searchTerms = $('Prep Context').first().json.searchTerms || [];
let replyText = ($input.first().json.output || '').trim();
function stripMd(s){
  s = String(s||'');
  // [text](url) -> text url
  let res='', i=0;
  while(i<s.length){
    if(s[i]==='['){
      const close=s.indexOf('](', i);
      if(close!==-1){
        const urlEnd=s.indexOf(')', close+2);
        if(urlEnd!==-1){
          const txt=s.slice(i+1, close);
          const url=s.slice(close+2, urlEnd);
          res += txt + ' ' + url;
          i=urlEnd+1; continue;
        }
      }
    }
    res += s[i]; i++;
  }
  // markdown bold/italic тэмдэг арилгах
  res = res.split('**').join('').split('__').join('');
  return res;
}
replyText = stripMd(replyText).trim();
if (!replyText) { replyText = 'Уучлаарай, түр алдаа гарлаа.'; }
// Давхардлаас хамгаалах (regex-гүй)
if (products.length > 0) {
  const lower = replyText;
  const hasUrl = lower.indexOf('http') !== -1;
  let hasNumberedList = false;
  const rl = replyText.split(NL);
  for (let li = 0; li < rl.length; li++) {
    const t = rl[li].replace(/s/g, ' ').trim();
    if (t.length > 1 && t.charCodeAt(0) >= 49 && t.charCodeAt(0) <= 57 && (t.charAt(1) === '.' || t.charAt(1) === ')')) { hasNumberedList = true; break; }
  }
  const tooLong = replyText.length > 600;
  if (hasUrl || hasNumberedList || tooLong) {
    const n = products.length;
    const termStr = searchTerms.length ? searchTerms.join(', ') : '';
    if (termStr) {
      replyText = 'Таны хайсан "' + termStr + '" холбоотой ' + n + ' бүтээгдэхүүн оллоо 👇 Доорх картуудаас сонгоод дэлгэрэнгүйг нь үзээрэй.';
    } else {
      replyText = 'Танд тохирох ' + n + ' бүтээгдэхүүн оллоо 👇 Доорх картуудаас үзээрэй.';
    }
  }
}
if (replyText.length > 1900) replyText = replyText.slice(0, 1897) + '...';
const clip = (s, m) => { s = String(s || '').split(NL).join(' ').trim(); while (s.indexOf('  ') !== -1) s = s.split('  ').join(' '); return s.length > m ? s.slice(0, m - 1).trim() + '…' : s; };
const fmt = (num0) => { let num = Math.round(Number(num0) || 0); let str = String(num); let out = ''; let c = 0; for (let i = str.length - 1; i >= 0; i--) { out = str[i] + out; c++; if (c % 3 === 0 && i > 0) out = ',' + out; } return out + TUG; };
const elements = products.slice(0, 10).map((p) => {
  const priceLine = (p.salePrice != null) ? ('💰 ' + fmt(p.salePrice) + '  ·  хуучин ' + fmt(p.price)) : ('💰 ' + fmt(p.price));
  const room = 79 - priceLine.length;
  const descShort = room > 12 ? clip(p.description, room) : '';
  const subtitle = descShort ? clip(priceLine + NL + descShort, 80) : clip(priceLine, 80);
  const el = { title: clip(p.title, 80), subtitle: subtitle, default_action: { type: 'web_url', url: p.url, webview_height_ratio: 'full' }, buttons: [ { type: 'web_url', url: p.url, title: 'Дэлгэрэнгүй үзэх' } ] };
  if (p.imageUrl) el.image_url = p.imageUrl;
  return el;
});
return [{ json: { psid, replyText, hasCards: elements.length > 0, elements } }];
